-- =============================================================================
-- RE-IMPORT: ETPL Digitide PPM, from the in-house tracker, correctly mapped
-- =============================================================================
-- Source : "ETPL PPM_Calendar_FY2026-27 - Copy.xlsx", sheet "Inhouse PPM Tracker"
-- Target : property ETPL Digitide (bf345711-06fc-405f-b3a6-0a4888fff8b2)
-- Built  : 2026-11-09. Run top to bottom in the Supabase SQL editor.
--
-- WHAT THIS REPLACES
--   The 364 ETPL rows now in the system came from this same sheet through
--   /api/ppm/upload, which read it one column group off: the floor landed in
--   frequency, a person landed in vendor_name, location was left empty, and the
--   first and last period columns were never read at all. That is why October
--   held 14 tasks instead of 75 and September held none.
--
--   This script deletes those rows and inserts 917 correctly mapped ones:
--     E -> location    F -> maker (Done By)    G -> checker (Verified by)
--     16 period triplets read from column H, not K.
--   Where "Done By" names a company rather than "Inhouse Team" (Metro Aircon on
--   the Voltas AC tasks, Accutech on the UPS tasks) that company also goes into
--   vendor_name, so those 29 rows show a vendor in the module.
--   Floor spellings are kept exactly as the sheet has them ("1st Floor" and
--   "1st floor" both appear); nothing is silently normalised.
--
-- WHAT YOU LOSE (checked, it is small)
--   Nothing references ppm_schedules by foreign key, and of the 364 rows:
--     0 have photos, certificates or invoices
--     0 have a vendor or asset link, 0 are in vendor verification
--     1 is marked done in the app and not in the sheet:
--       "Rodent  Panel HUB Room C Wing", planned 11-Oct-2025, done 23-Jul-2026
--       by Altamash Sirajuddin Chaugule. Step 4 restores exactly that one row.
--   Step 1 copies all 364 rows to ppm_schedules_etpl_backup_20261109 first, so
--   anything else can be recovered.
--
-- STATUS RULES APPLIED
--   remark "Done" + a done date up to today -> done
--   remark "Miss"                           -> skipped
--   remark "NA" / "N/A"                     -> row not created at all
--   a done date after today                 -> pending (the sheet pre-fills that
--                                              column, so it is a plan)
--   no planned date, only a done date        -> the done date becomes the planned
--                                              date (planned_date is NOT NULL)
--   frequency is derived per task from how many distinct months it appears in.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- STEP 1 - back up every ETPL row (run this on its own and check the count)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.ppm_schedules_etpl_backup_20261109 AS
SELECT * FROM public.ppm_schedules WHERE property_id = 'bf345711-06fc-405f-b3a6-0a4888fff8b2';

SELECT count(*) AS rows_backed_up FROM public.ppm_schedules_etpl_backup_20261109;   -- expect 364


-- -----------------------------------------------------------------------------
-- STEP 2 - replace the data (single transaction: both halves or neither)
-- -----------------------------------------------------------------------------
BEGIN;

DELETE FROM public.ppm_schedules WHERE property_id = 'bf345711-06fc-405f-b3a6-0a4888fff8b2';

