-- -----------------------------------------------------------------------------
-- STEP 4 - restore the one app-recorded completion the sheet does not carry
-- -----------------------------------------------------------------------------
-- Re-marks the Rodent Panel task done on 23-Jul-2026 and keeps the name of the
-- person who closed it. Matches on the new row, so run it after STEP 2.
--
-- CORRECTED 2026-11-09: this first shipped without "AND location", and
-- (detail_name, planned_date) is NOT unique here — the same task exists on four
-- floors, so it hit two rows. 191 of the 917 rows share such a pair. If you
-- already ran the earlier version, run fix_etpl_step4_overreach.sql.
UPDATE public.ppm_schedules SET
    status      = 'done',
    done_date   = DATE '2026-07-23',
    attachments = COALESCE(attachments, '{}'::jsonb) || jsonb_build_object(
                      'completed_by', '1a1d781a-1b3a-4dac-8d1b-1944ab5be743',
                      'completed_by_name', 'Altamash Sirajuddin Chaugule',
                      'completed_at', '2026-07-23T11:12:05.747Z',
                      'source', 'carried over from the pre-reimport row'
                  ),
    updated_at  = now()
WHERE property_id = 'bf345711-06fc-405f-b3a6-0a4888fff8b2'
  AND detail_name = 'Rodent  Panel HUB Room C Wing'
  AND planned_date = DATE '2025-10-11'
  AND location = '1st Floor';


